using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;

    const int INF = 1e9;

    // adjacency matrix
    vector<vector<int>> dist(n, vector<int>(n, INF));

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        dist[u][v] = min(dist[u][v], w);
    }

    // dp[mask][v] = min cost to reach v visiting exactly vertices in mask
    int total = 1 << n;
    vector<vector<int>> dp(total, vector<int>(n, INF));

    // Start at vertex 0
    dp[1][0] = 0;

    for (int mask = 1; mask < total; mask++) {
        for (int u = 0; u < n; u++) {
            if (dp[mask][u] == INF) continue;
            if (!(mask & (1 << u))) continue;

            // Try to go to next vertex v
            for (int v = 0; v < n; v++) {
                if (mask & (1 << v)) continue; // already visited
                if (dist[u][v] == INF) continue;

                int new_mask = mask | (1 << v);
                dp[new_mask][v] = min(dp[new_mask][v], dp[mask][u] + dist[u][v]);
            }
        }
    }

    // Find minimum cost to complete the tour (return to vertex 0)
    int full_mask = total - 1;
    int ans = INF;

    for (int u = 0; u < n; u++) {
        if (dp[full_mask][u] == INF) continue;
        if (dist[u][0] == INF) continue;
        ans = min(ans, dp[full_mask][u] + dist[u][0]);
    }

    if (ans == INF) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}

