const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // Distance matrix, initialized to INF
    vector<vector<int>> dist(n, vector<int>(n, INF));
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        dist[u][v] = min(dist[u][v], w); // keep smallest edge weight
    }

    // DP table: dp[mask][v] = min cost to start at 0, visit set 'mask', end at v
    vector<vector<int>> dp(1 << n, vector<int>(n, INF));
    dp[1][0] = 0; // start at vertex 0, only vertex 0 visited

    // Iterate over all masks
    for (int mask = 1; mask < (1 << n); mask++) {
        // If mask does not include start vertex 0, skip
        if (!(mask & 1)) continue;

        for (int v = 0; v < n; v++) {
            if (!(mask & (1 << v))) continue; // v not in mask
            if (dp[mask][v] == INF) continue;

            // Try to go to an unvisited vertex u
            for (int u = 0; u < n; u++) {
                if (mask & (1 << u)) continue; // already visited
                if (dist[v][u] == INF) continue; // no edge
                int newMask = mask | (1 << u);
                dp[newMask][u] = min(dp[newMask][u], dp[mask][v] + dist[v][u]);
            }
        }
    }

    int fullMask = (1 << n) - 1;
    int ans = INF;

    // Try closing the cycle from any final vertex back to 0
    for (int v = 1; v < n; v++) {
        if (dp[fullMask][v] == INF) continue;
        if (dist[v][0] == INF) continue;
        ans = min(ans, dp[fullMask][v] + dist[v][0]);
    }

    if (ans == INF) cout << -1 << "\n";
    else cout << ans << "\n";

    return 0;
}

