int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    const long long INF = (1LL << 60);
    vector<vector<long long>> w(n, vector<long long>(n, INF));

    for (int i = 0; i < m; ++i) {
        int u, v;
        long long c;
        cin >> u >> v >> c;
        --u; --v;
        w[u][v] = min(w[u][v], c);
    }

    if (n == 1) {
        cout << -1 << '\n';
        return 0;
    }

    int FULL = 1 << n;
    long long answer = INF;

    // Fix starting vertex at 0 to avoid counting the same Hamiltonian cycle multiple times.
    vector<vector<long long>> dp(FULL, vector<long long>(n, INF));
    dp[1][0] = 0;

    for (int mask = 0; mask < FULL; ++mask) {
        if (!(mask & 1)) continue; // start vertex 0 must be included
        for (int u = 0; u < n; ++u) {
            if (!(mask & (1 << u))) continue;
            if (dp[mask][u] == INF) continue;

            for (int v = 0; v < n; ++v) {
                if (mask & (1 << v)) continue;
                if (w[u][v] == INF) continue;
                int nmask = mask | (1 << v);
                dp[nmask][v] = min(dp[nmask][v], dp[mask][u] + w[u][v]);
            }
        }
    }

    int all = FULL - 1;
    for (int u = 1; u < n; ++u) {
        if (dp[all][u] == INF || w[u][0] == INF) continue;
        answer = min(answer, dp[all][u] + w[u][0]);
    }

    cout << (answer == INF ? -1 : answer) << '\n';
    return 0;
}

