int n;
int dist[MAXN][MAXN];
int dp[1 << MAXN][MAXN];

int main() {
    scanf("%d", &n);

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf("%d", &dist[i][j]);

    // Initialize dp
    int full = (1 << n);
    for (int mask = 0; mask < full; mask++)
        for (int i = 0; i < n; i++)
            dp[mask][i] = INF;

    dp[1][0] = 0; // Start at vertex 0, only vertex 0 visited

    for (int mask = 1; mask < full; mask++) {
        for (int i = 0; i < n; i++) {
            if (!(mask & (1 << i))) continue; // i not in mask
            if (dp[mask][i] == INF) continue;

            // Try to go to vertex j not in mask
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) continue; // j already visited
                if (dist[i][j] == 0 && i != j) continue; // no edge (assuming 0 means no edge)
                // Actually we need to handle no-edge differently
                int new_mask = mask | (1 << j);
                int new_cost = dp[mask][i] + dist[i][j];
                if (new_cost < dp[new_mask][j])
                    dp[new_mask][j] = new_cost;
            }
        }
    }

    int ans = INF;
    int full_mask = (1 << n) - 1;
    for (int i = 1; i < n; i++) {
        if (dp[full_mask][i] != INF && dist[i][0] != 0) {
            int total = dp[full_mask][i] + dist[i][0];
            if (total < ans) ans = total;
        }
    }

    if (ans == INF) printf("-1\n");
    else printf("%d\n", ans);

    return 0;
}

