        for (int u = 0; u < n; u++) {
            if (dp[mask][u] == INF) continue;
            if (!(mask & (1 << u))) continue;

            for (int v = 0; v < n; v++) {
                if (mask & (1 << v)) continue;
                if (w[u][v] == INF) continue;
                int nmask = mask | (1 << v);
                if (dp[nmask][v] > dp[mask][u] + w[u][v]) {
                    dp[nmask][v] = dp[mask][u] + w[u][v];
                }
            }
        }
    }

    int full = total - 1;
    int ans = INF;
    for (int u = 0; u < n; u++) {
        if (u == start) continue;
        if (dp[full][u] == INF || w[u][start] == INF) continue;
        ans = min(ans, dp[full][u] + w[u][start]);
    }

    if (ans == INF) printf("-1\n");
    else printf("%d\n", ans);

    for (int s = 0; s < total; s++) free(dp[s]);
    free(dp);
    for (int i = 0; i < n; i++) free(w[i]);
    free(w);

    return 0;
}

