import java.io.*;
import java.util.*;

public class Main {
    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        long[][] w = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(w[i], INF);
        }

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long c = fs.nextLong();
            if (c < w[u][v]) w[u][v] = c;
        }

        if (n == 1) {
            System.out.println(-1);
            return;
        }

        int start = 0;
        int fullMask = (1 << n) - 1;

        long[][] dp = new long[1 << n][n];
        for (int i = 0; i < (1 << n); i++) Arrays.fill(dp[i], INF);

        dp[1 << start][start] = 0;

        for (int mask = 0; mask <= fullMask; mask++) {
            if ((mask & (1 << start)) == 0) continue;

            for (int u = 0; u < n; u++) {
                long cur = dp[mask][u];
                if (cur == INF) continue;

                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0) continue;
                    if (w[u][v] == INF) continue;

                    int nextMask = mask | (1 << v);
                    long nd = cur + w[u][v];
                    if (nd < dp[nextMask][v]) {
                        dp[nextMask][v] = nd;
                    }
                }
            }
        }

        long ans = INF;
        for (int u = 0; u < n; u++) {
            if (u == start) continue;
            if (dp[fullMask][u] == INF || w[u][start] == INF) continue;
            ans = Math.min(ans, dp[fullMask][u] + w[u][start]);
        }

        System.out.println(ans == INF ? -1 : ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))

    INF = 10**15
    dist = [[INF] * n for _ in range(n)]

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        dist[u][v] = min(dist[u][v], w)

    # dp[mask][u] = min cost to start at 0, visit vertices in mask (including 0 and u), end at u
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0  # only vertex 0 visited

    for mask in range(1 << n):
        if not (mask & 1):
            continue
        for u in range(n):
            if not (mask >> u) & 1:
                continue
            if dp[mask][u] == INF:
                continue
            for v in range(n):
                if (mask >> v) & 1:
                    continue
                if dist[u][v] == INF:
                    continue
                new_mask = mask | (1 << v)
                dp[new_mask][v] = min(dp[new_mask][v], dp[mask][u] + dist[u][v])

    full_mask = (1 << n) - 1
    ans = INF
    for u in range(1, n):
        if dist[u][0] != INF and dp[full_mask][u] != INF:
            ans = min(ans, dp[full_mask][u] + dist[u][0])

    print(-1 if ans == INF else ans)

